cellular-automata.pseudocode:
def life_step(grid):
    # 콘웨이 생명 게임 (B3/S23), 경계는 토러스로 연결
    R, C = len(grid), len(grid[0])
    nxt = [[0] * C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            n = sum(grid[(r + dr) % R][(c + dc) % C]
                    for dr in (-1, 0, 1)
                    for dc in (-1, 0, 1)
                    if (dr, dc) != (0, 0))  # 무어 이웃 8칸
            if grid[r][c]:
                nxt[r][c] = 1 if n in (2, 3) else 0  # 생존
            else:
                nxt[r][c] = 1 if n == 3 else 0  # 탄생
    return nxt  # 새 격자에 기록 → 동시 갱신 보장

central-difference.pseudocode:
def forward_diff(f, x, h):
    return (f(x + h) - f(x)) / h  # 오차 O(h)

def central_diff(f, x, h):
    # 테일러 전개에서 h² 항까지 상쇄 → 오차 O(h²)
    return (f(x + h) - f(x - h)) / (2 * h)

def second_central(f, x, h):  # 2계 도함수 근사
    return (f(x + h) - 2 * f(x) + f(x - h)) / h ** 2

# f = sin, x = 1, h = 0.1 (참값 cos 1 = 0.5403)
# 전진 0.4974, 중앙 0.5394

certainty-factor.pseudocode:
def cf_combine(cf1, cf2):
    # 같은 가설에 대한 두 확신도 결합 (MYCIN)
    if cf1 >= 0 and cf2 >= 0:
        return cf1 + cf2 * (1 - cf1)
    if cf1 < 0 and cf2 < 0:
        return cf1 + cf2 * (1 + cf1)
    return (cf1 + cf2) / (1 - min(abs(cf1), abs(cf2)))

def cf_rule(cf_e, strength):
    # 증거 확신도가 양수일 때만 규칙 발화
    return cf_e * strength if cf_e > 0 else 0.0

# 전제 결합: AND → min(CF), OR → max(CF)
# 예: cf_combine(0.8, 0.6) = 0.8 + 0.6 × 0.2 = 0.92

certificate-chain.pseudocode:
def verify_chain(chain, trust_store, now):
    # chain[0]=서버 인증서, 이후 중간 CA 순서
    for i, cert in enumerate(chain):
        if not (cert.not_before <= now <= cert.not_after):
            return False  # 유효기간
        if is_revoked(cert):  # CRL·OCSP 확인
            return False
        if i + 1 < len(chain):
            issuer = chain[i + 1]
        else:
            issuer = trust_store.get(cert.issuer)
        if issuer is None:
            return False  # 신뢰 앵커 없음
        if cert.issuer != issuer.subject:
            return False  # 이름 연결 불일치
        if i > 0 and not cert.is_ca:
            return False  # 중간 인증서는 CA 권한 필요
        if not verify_sig(cert, issuer.public_key):
            return False  # 상위 공개키로 서명 검증
    return True

certificate-pinning.pseudocode:
# pins: 앱에 내장한 SPKI SHA-256 해시 집합(백업 핀 포함)
def check_pin(chain, pins):
    if not system_trust_verify(chain):
        return False  # 기본 TLS 검증 먼저
    for cert in chain:
        if sha256(cert.spki) in pins:
            return True  # 체인 내 하나라도 일치하면 통과
    return False  # 위조 CA 발급 인증서 차단
